<?php
namespace App\Http\Controllers;
use App\Models\{Product,BalanceChange}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class ProductController extends Controller { public function index(){return Product::latest()->get();} public function store(Request $r){return Product::create($r->validate(['name'=>'required','sku'=>'nullable','quantity'=>'integer','unit'=>'required|in:عدد,گرم,مثقال,انس']));} public function changeBalance(Request $r,Product $product){$d=$r->validate(['amount'=>'required|integer|not_in:0','note'=>'nullable']);return DB::transaction(function()use($d,$r,$product){$old=$product->quantity;$product->increment('quantity',$d['amount']);$product->refresh();return BalanceChange::create(['product_id'=>$product->id,'user_id'=>$r->session()->get('user_id'),'change_amount'=>$d['amount'],'previous_quantity'=>$old,'new_quantity'=>$product->quantity,'note'=>$d['note']??null]);});} public function history(Request $r){$q=BalanceChange::with(['product:id,name,unit','user:id,name'])->latest();if($r->from)$q->whereDate('created_at','>=',$r->from);if($r->to)$q->whereDate('created_at','<=',$r->to);return $q->get();} public function dashboard(){return ['products'=>Product::latest()->get(['id','name','sku','quantity','unit']),'changes_today'=>BalanceChange::whereDate('created_at',today())->count(),'users'=>\App\Models\User::count()];} }
